import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"卷一（乾、坤）","description":"伊川易传 - 卷一（乾、坤）","frontmatter":{"title":"卷一（乾、坤）","description":"伊川易传 - 卷一（乾、坤）"},"headers":[],"relativePath":"zh/classics/yichuan/002.md","filePath":"zh/classics/yichuan/002.md"}'),l={name:"zh/classics/yichuan/002.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="卷一-乾、坤" tabindex="-1">卷一（乾、坤） <a class="header-anchor" href="#卷一-乾、坤" aria-label="Permalink to “卷一（乾、坤）”">​</a></h1><p>《乾》：元，亨，利，贞。</p><p>上古圣人始画八卦，三才之道备矣。因而重之，以尽天下之变，故六画而成卦。重乾为《乾》。乾，天也。天者天之形体，乾者天之性情。乾，健也，健而无息之谓乾。夫天，专言之则道也，天且弗违是也；分而言之，则以形体谓之天，以主宰谓之帝，以功用谓之鬼神，以妙用谓之神，以性情谓之乾。乾者万物之始，故为天，为阳，为父，为君。元亨利贞谓之四德。元者万物之始，亨者万物之长，利者万物之遂，贞者万物之成。惟《乾》、《坤》有此四德，在他卦则随事而变焉。故元专为善大，利主于正固，亨贞之体，各称其事。四德之义，广矣大矣。</p><h3 id="《彖》曰-大哉乾元-万物资始乃统天。云行雨施-品物流形。大明终始-六位时成-时乘六龙以御天。乾道变化-各正性命-保合太和-乃利贞。首出庶物-万国咸宁。" tabindex="-1">《彖》曰：大哉乾元！万物资始乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合太和，乃利贞。首出庶物，万国咸宁。 <a class="header-anchor" href="#《彖》曰-大哉乾元-万物资始乃统天。云行雨施-品物流形。大明终始-六位时成-时乘六龙以御天。乾道变化-各正性命-保合太和-乃利贞。首出庶物-万国咸宁。" aria-label="Permalink to “《彖》曰：大哉乾元！万物资始乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合太和，乃利贞。首出庶物，万国咸宁。”">​</a></h3><p>卦下之辞为彖。夫子从而释之，通谓之彖。彖者，言一卦之义。故知者观其彖辞，则思过半矣。大哉乾元，赞乾元始万物之道大也。四德之元，犹五常之仁，偏言则一事，专言则包四者。万物资始乃统天，言元也。乾元统言天之道也。天道始万物，物资始于天也。云行雨施，品物流形，言亨也。天道运行，生育万物也。大明天道之终始，则见卦之六位，各以时成。卦之初终，乃天道终始。乘此六爻之时，乃天运也。以御天，谓以当天运。乾道变化，生育万物，洪纤高下，各以其类，各正性命也。天所赋为命，物所受为性。保合太和乃利贞，保谓常存，合谓常和，保合太和，是以利且贞也。天地之道，常久而不已者，保合太和也。天为万物之祖，王为万邦之宗。乾道首出庶物而万汇亨，君道尊临天位而四海从。王者体天之道，则万国咸宁也。</p><h3 id="象曰-天行健-君子以自强不息。" tabindex="-1">象曰：天行健，君子以自强不息。 <a class="header-anchor" href="#象曰-天行健-君子以自强不息。" aria-label="Permalink to “象曰：天行健，君子以自强不息。”">​</a></h3><p>卦下象解一卦之象，爻下象解一爻之象。诸卦皆取象以为法。乾道覆育之象至大，非圣人莫能体，欲人皆可取法也，故取其行健而已，至健固足以见天道也。君子以自强不息，法天行之健也。</p><h3 id="初九-潜龙勿用。-象曰-潜龙勿用-阳在下也。" tabindex="-1">初九，潜龙勿用。 象曰：潜龙勿用，阳在下也。 <a class="header-anchor" href="#初九-潜龙勿用。-象曰-潜龙勿用-阳在下也。" aria-label="Permalink to “初九，潜龙勿用。 象曰：潜龙勿用，阳在下也。”">​</a></h3><p>下爻为初。九，阳数之盛，故以名阳爻。理无形也，故假象以显义。乾以龙为象。龙之为物，灵变不测，故以象乾道变化，阳气消息，圣人进退。初九在一卦之下，为始物之端，阳气方萌。圣人侧微，若龙之潜隐，未可自用，当晦养以俟时。</p><p>阳气在下，君子处微，未可用也。</p><h3 id="九二-见龙在田-利见大人。-象曰-见龙在田-德施普也。" tabindex="-1">九二，见龙在田，利见大人。 象曰：见龙在田，德施普也。 <a class="header-anchor" href="#九二-见龙在田-利见大人。-象曰-见龙在田-德施普也。" aria-label="Permalink to “九二，见龙在田，利见大人。 象曰：见龙在田，德施普也。”">​</a></h3><p>田，地上也。出见于地上，其德已著。以圣人言之，舜之田渔时也。利见大德之君，以行其道。君亦利见大德之臣，以共成其功。天下利见大德之人，以被其泽。大德之君，九五也。乾坤纯体，不分刚柔，而以同德相应。</p><p>见于地上，德化及物，其施已普也。</p><h3 id="九三-君子终日乾乾-夕惕若-厉-无咎。-象曰-终日乾乾-反复道也。" tabindex="-1">九三，君子终日乾乾，夕惕若，厉，无咎。 象曰：终日乾乾，反复道也。 <a class="header-anchor" href="#九三-君子终日乾乾-夕惕若-厉-无咎。-象曰-终日乾乾-反复道也。" aria-label="Permalink to “九三，君子终日乾乾，夕惕若，厉，无咎。 象曰：终日乾乾，反复道也。”">​</a></h3><p>三虽人位，已在下体之上，未离于下而尊显者也。舜之玄德升闻时也。日夕不懈而兢惕，则虽处危地而无咎。在下之人而君德已著，天下将归之，其危惧可知。虽言圣人事，苟不设戒，则何以为教？作《易》之义也。</p><p>进退动息，必以道也。</p><h3 id="九四-或跃在渊-无咎。-象曰-或跃在渊-进无咎也。" tabindex="-1">九四，或跃在渊，无咎。 象曰：或跃在渊，进无咎也。 <a class="header-anchor" href="#九四-或跃在渊-无咎。-象曰-或跃在渊-进无咎也。" aria-label="Permalink to “九四，或跃在渊，无咎。 象曰：或跃在渊，进无咎也。”">​</a></h3><p>渊，龙之所安也。或，疑辞，谓非必也。跃不跃，惟及时以就安耳。圣人之动，无不时也。舜之历试，时也。</p><p>量可而进，适其时则无咎也。</p><h3 id="九五-飞龙在天-利见大人。-象曰-飞龙在天-大人造也。" tabindex="-1">九五，飞龙在天，利见大人。 象曰：飞龙在天，大人造也。 <a class="header-anchor" href="#九五-飞龙在天-利见大人。-象曰-飞龙在天-大人造也。" aria-label="Permalink to “九五，飞龙在天，利见大人。 象曰：飞龙在天，大人造也。”">​</a></h3><p>进位乎天位也。圣人既得天位，则利见在下大德之人，与共成天下之事。天下固利见夫大德之君也。</p><p>大人之为，圣人之事也。</p><h3 id="上九-亢龙-有悔。-象曰-亢龙有悔-盈不可久也。" tabindex="-1">上九，亢龙，有悔。 象曰：亢龙有悔，盈不可久也。 <a class="header-anchor" href="#上九-亢龙-有悔。-象曰-亢龙有悔-盈不可久也。" aria-label="Permalink to “上九，亢龙，有悔。 象曰：亢龙有悔，盈不可久也。”">​</a></h3><p>九五者，位之极中正者。得时之极，过此则亢矣。上九至于亢极，故有悔也。有过则有悔。唯圣人知进退存亡而无过，则不至于悔也。</p><p>盈则变，有悔也。</p><h3 id="用九-见群龙无首-吉。-象曰-用九-天德不可为首也。" tabindex="-1">用九，见群龙无首，吉。 象曰：用九，天德不可为首也。 <a class="header-anchor" href="#用九-见群龙无首-吉。-象曰-用九-天德不可为首也。" aria-label="Permalink to “用九，见群龙无首，吉。 象曰：用九，天德不可为首也。”">​</a></h3><p>用九者，处乾刚之道，以阳居乾体，纯乎刚者也。刚柔相济为中，而乃以纯刚，是过乎刚也。见群龙，谓观诸阳之义，无为首则吉也。以刚为天下先，凶之道也。</p><p>用九，天德也。天德阳刚，复用刚而好先，则过矣。</p><h3 id="《文言》曰-元者善之长也-亨者嘉之会也-利者义之和也-贞者事之乾也。" tabindex="-1">《文言》曰：元者善之长也，亨者嘉之会也，利者义之和也，贞者事之乾也。 <a class="header-anchor" href="#《文言》曰-元者善之长也-亨者嘉之会也-利者义之和也-贞者事之乾也。" aria-label="Permalink to “《文言》曰：元者善之长也，亨者嘉之会也，利者义之和也，贞者事之乾也。”">​</a></h3><p>他卦，《彖》、《象》而已，独《乾》、《坤》更设《文言》以发明其义，推乾之道，施于人事。元亨利贞，乾之四德，在人则元者众善之首也，亨者嘉美之会也，利者和合于义也，贞者乾事之用也。</p><h3 id="君子体仁足以长人" tabindex="-1">君子体仁足以长人， <a class="header-anchor" href="#君子体仁足以长人" aria-label="Permalink to “君子体仁足以长人，”">​</a></h3><p>体法于乾之仁，乃为君长之道，足以长人也。体仁，体元也。比而效之谓之体。</p><h3 id="嘉会足以合礼" tabindex="-1">嘉会足以合礼， <a class="header-anchor" href="#嘉会足以合礼" aria-label="Permalink to “嘉会足以合礼，”">​</a></h3><p>得会通之嘉，乃合于礼也。不合礼则非理，岂得为嘉？非理安有亨乎？</p><h3 id="利物足以和义" tabindex="-1">利物足以和义， <a class="header-anchor" href="#利物足以和义" aria-label="Permalink to “利物足以和义，”">​</a></h3><p>和于义乃能利物。岂有不得其宜，而能利物者乎？</p><h3 id="贞固足以乾事。" tabindex="-1">贞固足以乾事。 <a class="header-anchor" href="#贞固足以乾事。" aria-label="Permalink to “贞固足以乾事。”">​</a></h3><p>贞固所以能乾事也。</p><h3 id="君子行此四德者-故曰-乾-元亨利贞。" tabindex="-1">君子行此四德者，故曰“乾：元亨利贞。” <a class="header-anchor" href="#君子行此四德者-故曰-乾-元亨利贞。" aria-label="Permalink to “君子行此四德者，故曰“乾：元亨利贞。””">​</a></h3><p>行此四德，乃合于乾也。</p><h3 id="初九曰潜龙勿用-何谓也-子曰-龙德而隐者也。不易乎世-不成乎名-遁世无闷-不见是而无闷-乐则行之-忧则违之-确乎其不可拔-潜龙也。" tabindex="-1">初九曰潜龙勿用，何谓也？ 子曰：龙德而隐者也。不易乎世，不成乎名，遁世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。 <a class="header-anchor" href="#初九曰潜龙勿用-何谓也-子曰-龙德而隐者也。不易乎世-不成乎名-遁世无闷-不见是而无闷-乐则行之-忧则违之-确乎其不可拔-潜龙也。" aria-label="Permalink to “初九曰潜龙勿用，何谓也？ 子曰：龙德而隐者也。不易乎世，不成乎名，遁世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。”">​</a></h3><p>自此以下，言乾之用，用九之道也。初九阳之微，龙德之潜隐，乃圣贤之在侧陋也。守其道，不随世而变；晦其行，不求知于时；自信自乐，见可而动，知难而避，其守坚不可夺，潜龙之德也。</p><h3 id="九二曰见龙在田-利见大人-何谓也-子曰-龙德而正中者也-庸言之信-庸行之谨-闲邪存其诚-善世而不伐-德博而化。《易》曰-见龙在田-利见大人。-君德也。" tabindex="-1">九二曰见龙在田，利见大人，何谓也？ 子曰：龙德而正中者也，庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。《易》曰：“见龙在田，利见大人。”君德也。 <a class="header-anchor" href="#九二曰见龙在田-利见大人-何谓也-子曰-龙德而正中者也-庸言之信-庸行之谨-闲邪存其诚-善世而不伐-德博而化。《易》曰-见龙在田-利见大人。-君德也。" aria-label="Permalink to “九二曰见龙在田，利见大人，何谓也？ 子曰：龙德而正中者也，庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。《易》曰：“见龙在田，利见大人。”君德也。”">​</a></h3><p>以龙德而处正中者也。在卦之正中，为得正中之义。庸信庸谨，造次必于是也。既处无过之地，则唯在闲邪。邪既闲，则诚存矣。善世而不伐，不有其善也。德博而化，正己而物正也。皆大人之事，虽非君位，君之德也。</p><h3 id="九三曰君子终日乾乾-夕惕若-厉-无咎-何谓也-子曰-君子进德修业。忠信所以进德也。修辞立其诚-所以居业也。知至至之-可与几也-知终终之-可与存义也。是故居上位而不骄-在下位而不忧-故乾乾因其时而惕-虽危无咎矣。" tabindex="-1">九三曰君子终日乾乾，夕惕若，厉，无咎，何谓也？ 子曰：君子进德修业。忠信所以进德也。修辞立其诚，所以居业也。知至至之，可与几也；知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。 <a class="header-anchor" href="#九三曰君子终日乾乾-夕惕若-厉-无咎-何谓也-子曰-君子进德修业。忠信所以进德也。修辞立其诚-所以居业也。知至至之-可与几也-知终终之-可与存义也。是故居上位而不骄-在下位而不忧-故乾乾因其时而惕-虽危无咎矣。" aria-label="Permalink to “九三曰君子终日乾乾，夕惕若，厉，无咎，何谓也？ 子曰：君子进德修业。忠信所以进德也。修辞立其诚，所以居业也。知至至之，可与几也；知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。”">​</a></h3><p>三居下之上，而君德已著，将何为哉？唯进德修业而已。内积忠信，所以进德也。择言笃志，所以居业也。知至至之，致知也。求知所至而后至之，知之在先，故可与几，所谓“始条理者知之事也”。知终终之，力行也。既知所终，则力进而终之，守之在后，故可与存义，所谓“终条理者圣之事也”。此学之始终也。君子之学如是，故知处上下之道而无骄忧，不懈而知惧，虽在危地而无咎也。</p><h3 id="九四曰或跃在渊-无咎-何谓也-子曰-上下无常-非为邪也。进退无恒-非离群也。君子进德修业-欲及时也-故无咎。" tabindex="-1">九四曰或跃在渊，无咎，何谓也？ 子曰：上下无常，非为邪也。进退无恒，非离群也。君子进德修业，欲及时也，故无咎。 <a class="header-anchor" href="#九四曰或跃在渊-无咎-何谓也-子曰-上下无常-非为邪也。进退无恒-非离群也。君子进德修业-欲及时也-故无咎。" aria-label="Permalink to “九四曰或跃在渊，无咎，何谓也？ 子曰：上下无常，非为邪也。进退无恒，非离群也。君子进德修业，欲及时也，故无咎。”">​</a></h3><p>或跃或处，上下无常；或进或退，去就从宜；非为邪枉，非离群类，进德修业，欲及时耳。时行时止，不可恒也，故云或。深渊者，龙之所安也。在渊谓跃就所安。渊在深而言跃，但取进就所安之义。或，疑辞，随时而未可必也。君子之顺时，犹影之随形，可离非道也。</p><h3 id="九五曰飞龙在天-利见大人-何谓也-子曰-同声相应-同气相求-水流湿-火就燥-云从龙-风从虎-圣人作而万物睹。本乎天者亲上-本乎地者亲下-则各从其类也。" tabindex="-1">九五曰飞龙在天，利见大人，何谓也？ 子曰：同声相应，同气相求，水流湿，火就燥，云从龙，风从虎，圣人作而万物睹。本乎天者亲上，本乎地者亲下，则各从其类也。 <a class="header-anchor" href="#九五曰飞龙在天-利见大人-何谓也-子曰-同声相应-同气相求-水流湿-火就燥-云从龙-风从虎-圣人作而万物睹。本乎天者亲上-本乎地者亲下-则各从其类也。" aria-label="Permalink to “九五曰飞龙在天，利见大人，何谓也？ 子曰：同声相应，同气相求，水流湿，火就燥，云从龙，风从虎，圣人作而万物睹。本乎天者亲上，本乎地者亲下，则各从其类也。”">​</a></h3><p>人之与圣人，类也。五以龙德升尊位，人之类莫不归仰，况同德乎？上应于下，下从于上，同声相应，同气相求也。流湿就燥，从龙从虎，皆以气类，故圣人作而万物皆睹。上既见下，下亦见上。物，人也，古语云人物物论，谓人也。《易》中“利见大人”，其言则同，义则有异。如《讼》之利见大人，谓宜见大德中正之人，则其辩明，言在见前。《乾》之二五，则圣人既出，上下相见，共成其事，所利者见大人也，言在见后。本乎天者，如日月星辰。本乎地者，如虫兽草木。阴阳各从其类，人物莫不然也。</p><h3 id="上九曰亢龙有悔-何谓也-子曰-贵而无位-高而无民-贤人在下位而无辅-是以动而有悔也。" tabindex="-1">上九曰亢龙有悔，何谓也？ 子曰：贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。 <a class="header-anchor" href="#上九曰亢龙有悔-何谓也-子曰-贵而无位-高而无民-贤人在下位而无辅-是以动而有悔也。" aria-label="Permalink to “上九曰亢龙有悔，何谓也？ 子曰：贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”">​</a></h3><p>九居上而不当尊位，是以无民无辅，动则有悔也。</p><h3 id="潜龙勿用-下也。" tabindex="-1">潜龙勿用，下也。 <a class="header-anchor" href="#潜龙勿用-下也。" aria-label="Permalink to “潜龙勿用，下也。”">​</a></h3><p>此以下言乾之时。勿用，以在下未可用也。</p><h3 id="见龙在田-时舍也。" tabindex="-1">见龙在田，时舍也。 <a class="header-anchor" href="#见龙在田-时舍也。" aria-label="Permalink to “见龙在田，时舍也。”">​</a></h3><p>随时而止也。</p><h3 id="终日乾乾-行事也。" tabindex="-1">终日乾乾，行事也。 <a class="header-anchor" href="#终日乾乾-行事也。" aria-label="Permalink to “终日乾乾，行事也。”">​</a></h3><p>进德修业也。</p><h3 id="或跃在渊-自试也。" tabindex="-1">或跃在渊，自试也。 <a class="header-anchor" href="#或跃在渊-自试也。" aria-label="Permalink to “或跃在渊，自试也。”">​</a></h3><p>随时自用也。</p><h3 id="飞龙在天-上治也。" tabindex="-1">飞龙在天，上治也。 <a class="header-anchor" href="#飞龙在天-上治也。" aria-label="Permalink to “飞龙在天，上治也。”">​</a></h3><p>得位而行上之治也。</p><h3 id="亢龙有悔-穷之灾也。" tabindex="-1">亢龙有悔，穷之灾也。 <a class="header-anchor" href="#亢龙有悔-穷之灾也。" aria-label="Permalink to “亢龙有悔，穷之灾也。”">​</a></h3><p>穷极而灾至也。</p><h3 id="乾元用九-天下治也。" tabindex="-1">乾元用九，天下治也。 <a class="header-anchor" href="#乾元用九-天下治也。" aria-label="Permalink to “乾元用九，天下治也。”">​</a></h3><p>用九之道，天与圣人同，得其用则天下治也。</p><h3 id="潜龙勿用-阳气潜藏。" tabindex="-1">潜龙勿用，阳气潜藏。 <a class="header-anchor" href="#潜龙勿用-阳气潜藏。" aria-label="Permalink to “潜龙勿用，阳气潜藏。”">​</a></h3><p>此以下言乾之义。方阳微潜藏之时，君子亦当晦隐，未可用也。</p><h3 id="见龙在田-天下文明。" tabindex="-1">见龙在田，天下文明。 <a class="header-anchor" href="#见龙在田-天下文明。" aria-label="Permalink to “见龙在田，天下文明。”">​</a></h3><p>龙德见于地上，则天下见其文明之化也。</p><h3 id="终日乾乾-与时偕行。" tabindex="-1">终日乾乾，与时偕行。 <a class="header-anchor" href="#终日乾乾-与时偕行。" aria-label="Permalink to “终日乾乾，与时偕行。”">​</a></h3><p>随时而进也。</p><h3 id="或跃在渊-乾道乃革。" tabindex="-1">或跃在渊，乾道乃革。 <a class="header-anchor" href="#或跃在渊-乾道乃革。" aria-label="Permalink to “或跃在渊，乾道乃革。”">​</a></h3><p>离下位而升上位，上下革矣。</p><h3 id="飞龙在天-乃位乎天德。" tabindex="-1">飞龙在天，乃位乎天德。 <a class="header-anchor" href="#飞龙在天-乃位乎天德。" aria-label="Permalink to “飞龙在天，乃位乎天德。”">​</a></h3><p>正位乎上，位当天德。</p><h3 id="亢龙有悔-与时偕极。" tabindex="-1">亢龙有悔，与时偕极。 <a class="header-anchor" href="#亢龙有悔-与时偕极。" aria-label="Permalink to “亢龙有悔，与时偕极。”">​</a></h3><p>时既极，则处时者亦极矣。</p><h3 id="乾元用九-乃见天则。" tabindex="-1">乾元用九，乃见天则。 <a class="header-anchor" href="#乾元用九-乃见天则。" aria-label="Permalink to “乾元用九，乃见天则。”">​</a></h3><p>用九之道，天之则也。天之法则谓天道也。或问：《乾》之六爻皆圣人之事乎？曰：尽其道者圣人也。得失则吉凶存焉，岂特《乾》哉？诸卦皆然也。</p><h3 id="乾元者-始而亨者也。" tabindex="-1">乾元者，始而亨者也。 <a class="header-anchor" href="#乾元者-始而亨者也。" aria-label="Permalink to “乾元者，始而亨者也。”">​</a></h3><p>又反复详说以尽其义。既始则必亨，不亨则息矣。</p><h3 id="利贞者-性情也。" tabindex="-1">利贞者，性情也。 <a class="header-anchor" href="#利贞者-性情也。" aria-label="Permalink to “利贞者，性情也。”">​</a></h3><p>乾之性情也。既始而亨，非利贞其能不息乎？</p><h3 id="乾始能以美利利天下-不言所利-大矣哉" tabindex="-1">乾始能以美利利天下，不言所利，大矣哉！ <a class="header-anchor" href="#乾始能以美利利天下-不言所利-大矣哉" aria-label="Permalink to “乾始能以美利利天下，不言所利，大矣哉！”">​</a></h3><p>乾始之道，能使庶类生成，天下蒙其美利，而不言所利者，盖无所不利，非可指名也。故赞其利之大曰：“大矣哉！”</p><h3 id="大哉乾乎-刚、健-中、正-纯、粹-精也。六爻发挥-旁通情也。时乘六龙-以御天也。云行雨施-天下平也。" tabindex="-1">大哉乾乎！刚、健，中、正，纯、粹，精也。六爻发挥，旁通情也。时乘六龙，以御天也。云行雨施，天下平也。 <a class="header-anchor" href="#大哉乾乎-刚、健-中、正-纯、粹-精也。六爻发挥-旁通情也。时乘六龙-以御天也。云行雨施-天下平也。" aria-label="Permalink to “大哉乾乎！刚、健，中、正，纯、粹，精也。六爻发挥，旁通情也。时乘六龙，以御天也。云行雨施，天下平也。”">​</a></h3><p>大哉，赞乾道之大也。以刚、健、中、正、纯、粹六者，形容乾道。精谓六者之精极。以六爻发挥旁通，尽其情义。乘六爻之时以当天运，则天之功用着矣。故见云行雨施，阴阳溥畅，天下和平之道也。</p><h3 id="君子以成德为行-日可见之行也。潜之为言也-隐而未见-行而未成-是以君子弗用也。" tabindex="-1">君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。 <a class="header-anchor" href="#君子以成德为行-日可见之行也。潜之为言也-隐而未见-行而未成-是以君子弗用也。" aria-label="Permalink to “君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。”">​</a></h3><p>德之成，其事可见者行也。德成而后可施于用。初方潜隐未见，其行未成。未成，未著也，是以君子弗用也。</p><h3 id="君子学以聚之-问以辨之-宽以居之-仁以行之。《易》曰-见龙在田-利见大人。-君德也。" tabindex="-1">君子学以聚之，问以辨之，宽以居之，仁以行之。《易》曰：“见龙在田，利见大人。”君德也。 <a class="header-anchor" href="#君子学以聚之-问以辨之-宽以居之-仁以行之。《易》曰-见龙在田-利见大人。-君德也。" aria-label="Permalink to “君子学以聚之，问以辨之，宽以居之，仁以行之。《易》曰：“见龙在田，利见大人。”君德也。”">​</a></h3><p>圣人在下，虽已显而未得位，则进德修业而已。学、聚、问、辨，进德也。宽居、仁行，修业也。君德已著，利见大人，而进以行之耳。进居其位者，舜、禹也。进行其道者，伊、傅也。</p><h3 id="九三重刚而不中-上不在天-下不在田-故乾乾因其时而惕-虽危无咎矣。" tabindex="-1">九三重刚而不中，上不在天，下不在田，故乾乾因其时而惕，虽危无咎矣。 <a class="header-anchor" href="#九三重刚而不中-上不在天-下不在田-故乾乾因其时而惕-虽危无咎矣。" aria-label="Permalink to “九三重刚而不中，上不在天，下不在田，故乾乾因其时而惕，虽危无咎矣。”">​</a></h3><p>三重刚，刚之盛也。过中而居下之上，上未至于天，而下已离于田，危惧之地也。因时顺处，乾乾兢惕以防危，故虽危而不至于咎。君子顺时兢惕，所以能泰也。</p><h3 id="九四重刚而不中-上不在天-下不在田-中不在人-故或之。或之者-疑之也-故无咎。" tabindex="-1">九四重刚而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故无咎。 <a class="header-anchor" href="#九四重刚而不中-上不在天-下不在田-中不在人-故或之。或之者-疑之也-故无咎。" aria-label="Permalink to “九四重刚而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故无咎。”">​</a></h3><p>四不在天，不在田而出人之上矣，危地也。疑者未决之辞。处非可必也，或进或退，唯所安耳，所以无咎也。</p><h3 id="夫大人者-与天地合其德-与日月合其明-与四时合其序-与鬼神合其吉凶-先天而天弗违-后天而奉天时。天且弗违-而况于人乎-况于鬼神乎" tabindex="-1">夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶，先天而天弗违，后天而奉天时。天且弗违，而况于人乎？况于鬼神乎？ <a class="header-anchor" href="#夫大人者-与天地合其德-与日月合其明-与四时合其序-与鬼神合其吉凶-先天而天弗违-后天而奉天时。天且弗违-而况于人乎-况于鬼神乎" aria-label="Permalink to “夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶，先天而天弗违，后天而奉天时。天且弗违，而况于人乎？况于鬼神乎？”">​</a></h3><p>大人与天地日月四时鬼神合者，合乎道也。天地者道也，鬼神者造化之迹也。圣人先于天而天同之，后于天而能顺天者，合于道而已。合于道，则人与鬼神岂能违也？</p><h3 id="亢之为言也-知进而不知退-知存而不知亡-知得而不知丧。其唯圣人乎-知进退存亡而不失其正者-其唯圣人乎" tabindex="-1">亢之为言也，知进而不知退，知存而不知亡，知得而不知丧。其唯圣人乎！知进退存亡而不失其正者，其唯圣人乎！ <a class="header-anchor" href="#亢之为言也-知进而不知退-知存而不知亡-知得而不知丧。其唯圣人乎-知进退存亡而不失其正者-其唯圣人乎" aria-label="Permalink to “亢之为言也，知进而不知退，知存而不知亡，知得而不知丧。其唯圣人乎！知进退存亡而不失其正者，其唯圣人乎！”">​</a></h3><p>极之甚为亢。至于亢者，不知进退存亡得丧之理也。圣人则知而处之，皆不失其正，故不至于亢也。</p><p>《坤》：元，亨，利，牝马之贞。君子有攸往，先迷，后得，主利。西南得朋，东北丧朋，安贞，吉。</p><p>坤，乾之对也。四德同，而贞体则异。乾以刚固为贞，坤则柔顺而贞。牝马柔顺而健行，故取其象曰牝马之贞。</p><p>君子所行柔顺而利且贞，合坤德也。</p><p>阴，从阳者也，待唱而和。阴而先阳，则为迷错，居后乃得其常也。主利，利万物则主于坤，生成皆地之功也。臣道亦然，君令臣行，劳于事者臣之职也。</p><p>西南阴方，东北阳方。阴必从阳，离丧其朋类，乃能成化育之功，而有安贞之吉。得其常则安，安于常则贞，是以吉也。</p><h3 id="《彖》曰-至哉坤元-万物资生-乃顺承天。坤厚载物-德合无疆-含弘光大-品物咸亨。牝马地类-行地无疆-柔顺利贞-君子攸行。先迷失道-后顺得常。西南得朋-乃与类行-东北丧朋-乃终有庆。安贞之吉-应地无疆。" tabindex="-1">《彖》曰：至哉坤元！万物资生，乃顺承天。坤厚载物，德合无疆；含弘光大，品物咸亨。牝马地类，行地无疆；柔顺利贞，君子攸行。先迷失道，后顺得常。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。 <a class="header-anchor" href="#《彖》曰-至哉坤元-万物资生-乃顺承天。坤厚载物-德合无疆-含弘光大-品物咸亨。牝马地类-行地无疆-柔顺利贞-君子攸行。先迷失道-后顺得常。西南得朋-乃与类行-东北丧朋-乃终有庆。安贞之吉-应地无疆。" aria-label="Permalink to “《彖》曰：至哉坤元！万物资生，乃顺承天。坤厚载物，德合无疆；含弘光大，品物咸亨。牝马地类，行地无疆；柔顺利贞，君子攸行。先迷失道，后顺得常。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。”">​</a></h3><p>资生之道，可谓大矣。乾既称大，故坤称至。至义差缓，不若大之盛也。圣人于尊卑之辨，谨严如此。万物资乾以始，资坤以生，父母之道也。顺承天施，以成其功，坤之厚德，持载万物，合于乾之无疆也。</p><p>以含、弘、光、大四者形容坤道，犹乾之刚、健、中、正、纯、粹也。含，包容也。弘，宽裕也。光，昭明也。大，博厚也。有此四者，故能成承天之功，品物咸得亨遂。取牝马为象者，以其柔顺而健行，地之类也。行地无疆，谓健也。乾健坤顺，坤亦健乎？曰：非健何以配乾？未有乾行而坤止也。其动也刚，不害其为柔也。柔顺而利贞，乃坤德也，君子之所行也。君子之道合坤德也。</p><p>乾之用，阳之为也。坤之用，阴之为也。形而上曰天地之道，形而下曰阴阳之功。先迷后得以下，言阴道也。先唱则迷失阴道，后和则顺而得其常理。西南阴方，从其类，得朋也。东北阳方，离其类，丧朋也。离其类而从阳，则能成生物之功，终有吉庆也。与类行者本也，从于阳者用也。阴体柔躁，故从于阳则能安贞而吉，应地道之无疆也。阴而不安贞，岂能应地之道。《彖》有三无疆，盖不同也。“德合无疆”，天之不已也。“应地无疆”，地之无穷也。“行地无疆”，马之健行也。</p><h3 id="象曰-地势坤-君子以厚德载物。" tabindex="-1">象曰：地势坤，君子以厚德载物。 <a class="header-anchor" href="#象曰-地势坤-君子以厚德载物。" aria-label="Permalink to “象曰：地势坤，君子以厚德载物。”">​</a></h3><p>坤道之大犹乾也，非圣人孰能体之？地厚而其势顺倾，故取其顺厚之象，而云地势坤也。君子观坤厚之象，以深厚之德，容载庶物。</p><h3 id="初六-履霜-坚冰至。-象曰-履霜坚冰-阴始凝也-驯致其道-至坚冰也。" tabindex="-1">初六，履霜，坚冰至。 象曰：履霜坚冰，阴始凝也；驯致其道，至坚冰也。 <a class="header-anchor" href="#初六-履霜-坚冰至。-象曰-履霜坚冰-阴始凝也-驯致其道-至坚冰也。" aria-label="Permalink to “初六，履霜，坚冰至。 象曰：履霜坚冰，阴始凝也；驯致其道，至坚冰也。”">​</a></h3><p>阴爻称六，阴之盛也。八则阳生矣，非纯盛也。阴始生于下，至微也。圣人于阴之始生，以其将长，则为之戒。阴之始凝而为霜，履霜则当知阴渐盛而至坚冰矣。犹小人始虽甚微，不可使长，长则至于盛也。</p><p>阴始凝而为霜，渐盛则至于坚冰。小人虽微，长则渐至于盛，故戒于初。驯谓习，习而至于盛，习因循也。</p><h3 id="六二-直、方、大-不习无不利。-象曰-六二之动-直以方也。不习无不利-地道光也。" tabindex="-1">六二，直、方、大，不习无不利。 象曰：六二之动，直以方也。不习无不利，地道光也。 <a class="header-anchor" href="#六二-直、方、大-不习无不利。-象曰-六二之动-直以方也。不习无不利-地道光也。" aria-label="Permalink to “六二，直、方、大，不习无不利。 象曰：六二之动，直以方也。不习无不利，地道光也。”">​</a></h3><p>二，阴位在下，故为坤之主，统言坤道中正在下，地之道也。以直方大三者形容其德用，尽地之道矣。由直、方、大，故不习而无所不利。不习谓其自然，在坤道则莫之为而为也，在圣人则从容中道也。直、方、大，孟子所谓至大至刚以直也。在坤体，故以方易刚，犹贞加牝马也。言气，则先大。大，气之体也。于坤，则先直方，由直方而大也。直方大足以尽地道，在人识之耳。乾坤纯体，以位相应。二，坤之主，故不取五应，不以君道处五也。乾则二五相应。</p><p>承天而动，直以方耳，直方则大矣。直方之义，其大无穷，地道光显，其功顺成。岂习而后利哉？</p><h3 id="六三-含章可贞-或从王事-无成有终。-象曰-含章可贞-以时发也。或从王事-知光大也。" tabindex="-1">六三，含章可贞，或从王事，无成有终。 象曰：含章可贞，以时发也。或从王事，知光大也。 <a class="header-anchor" href="#六三-含章可贞-或从王事-无成有终。-象曰-含章可贞-以时发也。或从王事-知光大也。" aria-label="Permalink to “六三，含章可贞，或从王事，无成有终。 象曰：含章可贞，以时发也。或从王事，知光大也。”">​</a></h3><p>三居下之上，得位者也。为臣之道，当含晦其章美，有善则归之于君，乃可常而得正。上无忌恶之心，下得柔顺之道也。可贞谓可贞固守之，又可以常久而无悔咎也。或从上之事，不敢当其成功，惟奉事以守其终耳。守职以终其事，臣之道也。</p><p>夫子惧人之守文而不达义也，又从而明之：言为臣处下之道，不当有其功善，必含晦其美，乃正而可常；然义所当为者，则以时而发，不有其功耳。不失其宜，乃以时也，非含藏终不为也。含而不为，不尽忠者也。</p><p>象只举上句解义，则并及下文，他卦皆然。或从王事，而能无成有终者，是其知之光大也。唯其知之光大，故能含晦。浅暗之人有善唯恐人之不知，岂能含章也。</p><h3 id="六四-括囊无咎-无誉。-象曰-括囊无咎-慎不害也。" tabindex="-1">六四，括囊无咎，无誉。 象曰：括囊无咎，慎不害也。 <a class="header-anchor" href="#六四-括囊无咎-无誉。-象曰-括囊无咎-慎不害也。" aria-label="Permalink to “六四，括囊无咎，无誉。 象曰：括囊无咎，慎不害也。”">​</a></h3><p>四居近五之位，而无相得之义，乃上下闭隔之时。其自处以正，危疑之地也。若晦藏其知，如括结囊口而不露，则可得无咎，不然则有害也。既晦藏，则无誉矣。</p><p>能慎如此，则无害也。</p><h3 id="六五-黄裳元吉。-象曰-黄裳元吉-文在中也。" tabindex="-1">六五，黄裳元吉。 象曰：黄裳元吉，文在中也。 <a class="header-anchor" href="#六五-黄裳元吉。-象曰-黄裳元吉-文在中也。" aria-label="Permalink to “六五，黄裳元吉。 象曰：黄裳元吉，文在中也。”">​</a></h3><p>坤虽臣道，五实君位，故为之戒云，黄裳元吉。黄，中色。裳，下服。守中而居下，则元吉，谓守其分也。元，大而善也。爻象唯言守中居下则元吉，不尽发其义也。黄裳既元吉，则居尊为天下大凶可知。后之人未达，则此义晦矣，不得不辨也。五，尊位也。在他卦，六居五，或为柔顺，或为文明，或为暗弱；在坤，则为居尊位。阴者臣道也，妇道也。臣居尊位，羿、莽是也，犹可言也。妇居尊位，女娲氏、武氏是也，非常之变，不可言也，故有黄裳之戒而不尽言也。或疑在《革》，汤、武之事犹尽言之，独于此不言，何也？曰：废兴，理之常也。以阴居尊位，非常之变也。</p><p>黄中之文，在中不过也。内积至美而居下，故为元吉。</p><h3 id="上六-龙战于野-其血玄黄。-象曰-龙战于野-其道穷也。" tabindex="-1">上六，龙战于野，其血玄黄。 象曰：龙战于野，其道穷也。 <a class="header-anchor" href="#上六-龙战于野-其血玄黄。-象曰-龙战于野-其道穷也。" aria-label="Permalink to “上六，龙战于野，其血玄黄。 象曰：龙战于野，其道穷也。”">​</a></h3><p>阴从阳者也，然盛极则抗而争。六既极矣，复进不已，则必战，故云战于野。野谓进至于外也。既敌矣，必皆伤，故其血玄黄。</p><p>阴盛至于穷极，则必争而伤也。</p><h3 id="用六-利永贞。-象曰-用六永贞-以大终也。" tabindex="-1">用六，利永贞。 象曰：用六永贞，以大终也。 <a class="header-anchor" href="#用六-利永贞。-象曰-用六永贞-以大终也。" aria-label="Permalink to “用六，利永贞。 象曰：用六永贞，以大终也。”">​</a></h3><p>坤之用六，犹乾之用九，用阴之道也。阴道柔而难常，故用六之道，利在常永贞固。</p><p>阴既贞固不足，则不能永终。故用六之道，利在盛大于终，能大于终，乃永贞也。</p><h3 id="《文言》曰-坤至柔而动也刚-至静而德方。后得主而有常-含万物而化光。坤道其顺乎-承天而时行。" tabindex="-1">《文言》曰：坤至柔而动也刚，至静而德方。后得主而有常，含万物而化光。坤道其顺乎！承天而时行。 <a class="header-anchor" href="#《文言》曰-坤至柔而动也刚-至静而德方。后得主而有常-含万物而化光。坤道其顺乎-承天而时行。" aria-label="Permalink to “《文言》曰：坤至柔而动也刚，至静而德方。后得主而有常，含万物而化光。坤道其顺乎！承天而时行。”">​</a></h3><p>坤道至柔，而其动则刚；坤体至静，而其德则方。动刚故应乾不违，德方故生物有常。阴之道不唱而和，故居后为得，而主利成万物，坤之常也。含容万类，其功化光大也。主字下脱“利”字。坤道其顺乎，承天而时行，承天之施，行不违时，赞坤道之顺也。</p>',135)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
